/**
 * Slider confirm bar - drag to the right end to confirm
 */
export function SliderConfirmBar({
  onConfirm,
  label = "Slide to confirm",
  confirmThreshold = 90,
  disabled = false,
  icon,
}: SliderConfirmBarProps): JSX.Element {
  const [dragProgress, setDragProgress] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const sliderRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (disabled) return;
    e.preventDefault();
    setIsDragging(true);
  };

  useEffect(() => {
    if (!isDragging) return;

    const handleMouseMove = (e: MouseEvent) => {
      if (!sliderRef.current || disabled) return;

      const rect = sliderRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const maxX = rect.width;
      const progress = Math.max(0, Math.min(100, (x / maxX) * 100));

      setDragProgress(progress);
    };

    const handleMouseUp = () => {
      if (disabled) return;

      if (dragProgress >= confirmThreshold) {
        onConfirm();
        // Reset after a brief delay to show completion
        setTimeout(() => {
          setDragProgress(0);
        }, 200);
      } else {
        // Reset if not confirmed
        setDragProgress(0);
      }
      setIsDragging(false);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);

    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };
  }, [isDragging, dragProgress, confirmThreshold, onConfirm, disabled]);

  const isConfirmed = dragProgress >= confirmThreshold;

  return (
    <div
      ref={sliderRef}
      className={`slider-confirm-bar ${disabled ? "disabled" : ""} ${isDragging ? "dragging" : ""}`}
    >
      {/* Progress fill */}
      <div
        className={`slider-confirm-bar-progress ${isConfirmed ? "confirmed" : "default"} ${isDragging ? "no-transition" : ""}`}
        style={{
          width: `${dragProgress}%`,
        }}
      />
      {/* Label */}
      <div className="slider-confirm-bar-label">
        {isConfirmed ? "Release to confirm" : label}
      </div>
      {/* Draggable thumb */}
      <div
        ref={thumbRef}
        onMouseDown={handleMouseDown}
        className={`slider-confirm-bar-thumb ${disabled ? "disabled" : ""} ${isDragging ? "dragging" : ""} ${isConfirmed ? "confirmed" : ""}`}
        style={{
          left: `${dragProgress}%`,
        }}
      >
        {icon ? (
          <span className={`slider-confirm-bar-thumb-icon ${isConfirmed ? "confirmed" : ""}`}>
            {icon}
          </span>
        ) : (
          <span className={`slider-confirm-bar-thumb-arrow ${isConfirmed ? "confirmed" : ""}`}>
            →
          </span>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// Number Pad Component
// ============================================================================

/**
 * Number Pad Component for entering numeric values
 */
export function NumberPad({
  isOpen,
  value,
  min,
  max,
  onConfirm,
  onCancel,
}: NumberPadProps): JSX.Element | null {
  const [displayValue, setDisplayValue] = useState<string>("");

  // Initialize display value when modal opens
  useEffect(() => {
    if (isOpen) {
      setDisplayValue(value.toString());
    }
  }, [isOpen, value]);

  if (!isOpen) return null;

  const handleNumberClick = (num: string) => {
    const newValue = displayValue === "0" ? num : displayValue + num;
    const numValue = parseFloat(newValue);

    // Validate against min/max
    if (numValue <= max) {
      setDisplayValue(newValue);
    }
  };

  const handleDecimalClick = () => {
    if (!displayValue.includes(".")) {
      setDisplayValue(displayValue + ".");
    }
  };

  const handleBackspace = () => {
    if (displayValue.length > 1) {
      setDisplayValue(displayValue.slice(0, -1));
    } else {
      setDisplayValue("0");
    }
  };

  const handleClear = () => {
    setDisplayValue("0");
  };

  const handleConfirm = () => {
    const numValue = parseFloat(displayValue) || 0;
    const clampedValue = Math.max(min, Math.min(max, numValue));
    onConfirm(clampedValue);
  };

  const currentValue = parseFloat(displayValue) || 0;
  const isValid = currentValue >= min && currentValue <= max;

  const numberPadContent = (
    <div className="modal-overlay" onClick={onCancel} style={{ zIndex: 10000 }}>
      <div
        className="modal-content number-pad-content"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-header">
          <h3>Enter Amount</h3>
        </div>
        <div className="modal-body">
          {/* Display at top */}
          <div className="number-pad-display">
            <div className="number-pad-display-value">
              {formatCurrency(currentValue)}
            </div>
            <div className="number-pad-display-range">
              Min: {formatCurrency(min)} | Max: {formatCurrency(max)}
            </div>
            {!isValid && currentValue > 0 && (
              <div className="number-pad-display-error">
                Value must be between {formatCurrency(min)} and{" "}
                {formatCurrency(max)}
              </div>
            )}
          </div>

          {/* Number Pad Grid */}
          <div className="number-pad-grid">
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "1")}
            >
              1
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "2")}
            >
              2
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "3")}
            >
              3
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "4")}
            >
              4
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "5")}
            >
              5
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "6")}
            >
              6
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "7")}
            >
              7
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "8")}
            >
              8
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "9")}
            >
              9
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleDecimalClick}
            >
              .
            </button>
            <button
              type="button"
              className="number-pad-button"
              onClick={handleNumberClick.bind(null, "0")}
            >
              0
            </button>
            <button
              type="button"
              className="number-pad-button number-pad-button-action"
              onClick={handleBackspace}
            >
              ⌫
            </button>
          </div>

          {/* Action Buttons */}
          <div className="number-pad-actions">
            <button
              type="button"
              className="number-pad-action-button"
              onClick={handleClear}
            >
              Clear
            </button>
            <button
              type="button"
              className="number-pad-action-button number-pad-action-button-max"
              onClick={() => {
                setDisplayValue(max.toString());
              }}
            >
              Max
            </button>
          </div>
        </div>
        <div className="modal-footer">
          <button onClick={onCancel} className="btn btn-secondary">
            Cancel
          </button>
          <button
            onClick={handleConfirm}
            className="btn btn-primary"
            disabled={!isValid}
          >
            Confirm
          </button>
        </div>
      </div>
    </div>
  );

  return typeof document !== "undefined"
    ? createPortal(numberPadContent, document.body)
    : null;
}
